import numpy as np
from scipy import ndimage
a=np.array(g)
H,W=a.shape
out=a.copy()
# background = most common color
colors,counts=np.unique(a,return_counts=True)
bg=colors[counts.argmax()]
# blocks: connected components per color with size>=4
visited=np.zeros_like(a,bool)
noise=[]
for r in range(H):
    for c in range(W):
        v=a[r,c]
        if v==bg or visited[r,c]: continue
        mask=(a==v)&~visited
        lab,n=ndimage.label(mask)  # 4-connectivity
        for i in range(1,n+1):
            comp=np.argwhere(lab==i)
            visited[comp[:,0],comp[:,1]]=True
            if len(comp)>=4:
                r0,r1=comp[:,0].min(),comp[:,0].max()
                c0,c1=comp[:,1].min(),comp[:,1].max()
                # fill noise cells inside bbox
                for rr in range(r0,r1+1):
                    for cc in range(c0,c1+1):
                        if a[rr,cc]!=v:
                            noise.append((rr,cc,v))
            else:
                for rr,cc in comp:
                    noise.append((rr,cc,None))
# resolve noise: inside a block bbox -> block color, else bg
for rr,cc,v in noise:
    out[rr,cc]= v if v is not None else bg
for r in out: print(''.join(str(x) if x else '.' for x in r))
print(sorted(set(out.flatten().tolist())))

a=np.array(g); H,W=a.shape
colors,counts=np.unique(a,return_counts=True); bg=colors[counts.argmax()]
blocks=[]; blockmask=np.zeros_like(a,bool)
for v in colors:
    if v==bg: continue
    lab,n=ndimage.label(a==v)
    for i in range(1,n+1):
        comp=np.argwhere(lab==i)
        if len(comp)>=4:
            blocks.append((v,comp[:,0].min(),comp[:,0].max(),comp[:,1].min(),comp[:,1].max()))
            blockmask[lab==i]=True
out=a.copy()
for r in range(H):
    for c in range(W):
        if a[r,c]==bg or blockmask[r,c]: continue
        val=bg
        for v,r0,r1,c0,c1 in blocks:
            if r0<=r<=r1 and c0<=c<=c1: val=v
        out[r,c]=val
for r in out: print(''.join(str(x) if x else '.' for x in r))
print(sorted(set(out.flatten().tolist())))
